// Deployment guard: a stray index.html at the repo root (leftover from the
// legacy SPA setup) makes hosting serve a static shell that points at
// /src/main.tsx, which is served as text/html — causing the blank page with
// "Failed to load module script ... MIME type text/html". Fail the build
// loudly instead of shipping a blank app.
import { existsSync, readFileSync } from "node:fs";

const failures = [];

if (existsSync("index.html")) {
  failures.push(
    "index.html exists at the repo root. This is a TanStack Start SSR app; " +
      "the root HTML shell is generated by the server entry (src/server.ts). " +
      "Delete the stray index.html before building.",
  );
}

// Belt-and-braces: if a build output exists, no emitted HTML may reference
// a raw /src/ module path (that only happens with the broken static shell).
for (const candidate of ["dist/client/index.html", ".output/public/index.html"]) {
  if (existsSync(candidate)) {
    const html = readFileSync(candidate, "utf8");
    if (html.includes('src="/src/') || html.includes("src='/src/")) {
      failures.push(
        `${candidate} references a raw /src/ module — the build produced the ` +
          "legacy static shell instead of bundled assets. Remove any root " +
          "index.html and rebuild.",
      );
    }
  }
}

if (failures.length > 0) {
  console.error("Deployment guard failed:\n" + failures.map((f) => `  - ${f}`).join("\n"));
  process.exit(1);
}
